import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _to_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float)):
        return str(value)
    if isinstance(value, dict):
        for key in ("Text", "Value", "value", "text", "Name", "name", "Description", "description"):
            if key in value and value[key] is not None:
                return _to_text(value[key])
        return json.dumps(value, ensure_ascii=False)
    return str(value)


def _to_float(value: Any) -> Optional[float]:
    try:
        if value is None:
            return None
        if isinstance(value, (int, float)):
            return float(value)
        s = _to_text(value).strip()
        if not s:
            return None
        s = "".join(ch for ch in s if ch.isdigit() or ch in ".-")
        if s in ("", "-", ".", "-.", ".-"):
            return None
        return float(s)
    except Exception:
        return None


def _extract_text_from_expense_summary(summary_fields: List[Dict[str, Any]], field_type: str) -> str:
    for field in summary_fields or []:
        if str(field.get("Type", {}).get("Text", "")).lower() == field_type.lower():
            val = field.get("ValueDetection", {}).get("Text", "")
            if val:
                return val
    return ""


def _parse_items(expense_documents: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for doc in expense_documents or []:
        line_items_groups = doc.get("LineItemGroups", []) or []
        for group in line_items_groups:
            for line_item in group.get("LineItems", []) or []:
                item: Dict[str, Any] = {}
                for field in line_item.get("LineItemExpenseFields", []) or []:
                    field_type = str(field.get("Type", {}).get("Text", "")).lower()
                    val_text = field.get("ValueDetection", {}).get("Text", "")
                    if field_type in {"item", "description", "product", "name"}:
                        item["description"] = val_text
                    elif field_type in {"quantity", "qty"}:
                        item["quantity"] = _to_float(val_text)
                    elif field_type in {"unit_price", "unitprice", "price"}:
                        item["unit_price"] = _to_float(val_text)
                    elif field_type in {"amount", "total", "line_total"}:
                        item["amount"] = _to_float(val_text)
                if item:
                    items.append(item)
    return items


def extract_receipt(path: str) -> Dict[str, Any]:
    client = boto3.client("textract")
    with open(path, "rb") as f:
        document_bytes = f.read()

    response = client.analyze_expense(Document={"Bytes": document_bytes})

    expense_documents = response.get("ExpenseDocuments", []) or []
    merchant = ""
    tax = None
    total = None

    if expense_documents:
        summary_fields = expense_documents[0].get("SummaryFields", []) or []
        merchant = (
            _extract_text_from_expense_summary(summary_fields, "VENDOR_NAME")
            or _extract_text_from_expense_summary(summary_fields, "SUPPLIER_NAME")
            or _extract_text_from_expense_summary(summary_fields, "RECEIVER_NAME")
        )

        tax_text = (
            _extract_text_from_expense_summary(summary_fields, "TAX")
            or _extract_text_from_expense_summary(summary_fields, "TOTAL_TAX")
            or _extract_text_from_expense_summary(summary_fields, "TAX_AMOUNT")
        )
        total_text = (
            _extract_text_from_expense_summary(summary_fields, "TOTAL")
            or _extract_text_from_expense_summary(summary_fields, "AMOUNT_DUE")
            or _extract_text_from_expense_summary(summary_fields, "INVOICE_TOTAL")
        )

        tax = _to_float(tax_text)
        total = _to_float(total_text)

    items = _parse_items(expense_documents)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        raise SystemExit("Usage: python script.py /path/to/receipt_image_or_pdf")
    print(json.dumps(extract_receipt(sys.argv[1]), ensure_ascii=False, indent=2))
